/* ui/limiter.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../context.js";

export function install(P) {


  function updateLimiterMeter() {
    const meter = P.limiterEnabled ? P.ensureLimiterMeter() : null;
    let db = -Infinity;
    if (meter) {
      const buf = new Uint8Array(meter.fftSize);
      meter.getByteTimeDomainData(buf);
      let peak = 0;
      for (let i = 0; i < buf.length; i++) {
        const s = Math.abs((buf[i] - 128) / 128);
        if (s > peak) peak = s;
      }
      P.limiterPeak = peak;
      db = peak > 0 ? 20 * Math.log10(peak) : -Infinity;
      const now = performance.now();
      if (db >= P.limiterPeakHold || now - P.limiterPeakHoldAt > 1200) {
        P.limiterPeakHold = db;
        P.limiterPeakHoldAt = now;
      }
    } else {
      P.limiterPeak = 0;
      P.limiterPeakHold = -Infinity;
    }

    const pct = (value) => {
      if (!Number.isFinite(value)) return 0;
      return P.clamp(((value + 60) / 60) * 100, 0, 100);
    };
    const dbText = Number.isFinite(db) ? `${db.toFixed(1)} dBFS` : "-∞ dBFS";
    document.querySelectorAll("#playerLimiterValue").forEach((el) => { el.textContent = dbText; });
    document.querySelectorAll("#playerLimiterFill").forEach((el) => { el.style.width = `${pct(db)}%`; });
    document.querySelectorAll("#playerLimiterHold").forEach((el) => { el.style.left = `${pct(P.limiterPeakHold)}%`; });

    if (!P.settingsPanel || P.settingsPanel.hidden) {
      P.limiterMeterRaf = 0;
      return;
    }
    P.limiterMeterRaf = window.requestAnimationFrame(updateLimiterMeter);
  }

  function startLimiterMeter() {
    if (P.limiterMeterRaf) return;
    P.limiterMeterRaf = window.requestAnimationFrame(P.updateLimiterMeter);
  }

  function stopLimiterMeter() {
    if (P.limiterMeterRaf) {
      window.cancelAnimationFrame(P.limiterMeterRaf);
      P.limiterMeterRaf = 0;
    }
  }
  Object.assign(P, { updateLimiterMeter, startLimiterMeter, stopLimiterMeter });
}
